<?php require_once 'config.php';require_once 'auth.php';$action=$_POST['action']??'';if($action!=='connexion' && $action!=='deconnexion') exiger_connexion();switch($action){case 'connexion':if(trim($_POST['identifiant']??'')===$identifiant_admin && ($_POST['mot_de_passe']??'')===$mot_de_passe_admin){session_regenerate_id(true);$_SESSION['connecte']=true;header('Location:index.php');}else header('Location:connexion.php?erreur=1');break;case 'deconnexion':session_unset();session_destroy();header('Location:connexion.php');break;case 'ajouter':$s=$connexion->prepare('INSERT INTO employes(matricule,nom,prenom,poste,salaire,date_embauche) VALUES(?,?,?,?,?,?)');$s->bind_param('ssssds',$_POST['matricule'],$_POST['nom'],$_POST['prenom'],$_POST['poste'],$_POST['salaire'],$_POST['date_embauche']);$s->execute();header('Location:index.php?ok=ajoute');break;case 'modifier':$s=$connexion->prepare('UPDATE employes SET matricule=?,nom=?,prenom=?,poste=?,salaire=?,date_embauche=? WHERE id=?');$s->bind_param('ssssdsi',$_POST['matricule'],$_POST['nom'],$_POST['prenom'],$_POST['poste'],$_POST['salaire'],$_POST['date_embauche'],$_POST['id']);$s->execute();header('Location:index.php?ok=modifie');break;case 'supprimer':$s=$connexion->prepare('DELETE FROM employes WHERE id=?');$s->bind_param('i',$_POST['id']);$s->execute();header('Location:index.php?ok=supprime');break;case 'enregistrer_presences':$s=$connexion->prepare('INSERT INTO presences(employe_id,date_jour,statut) VALUES(?,?,?) ON DUPLICATE KEY UPDATE statut=VALUES(statut)');foreach($_POST['statut']??[] as $id=>$st){$id=(int)$id;$st=$st==='absent'?'absent':'present';$s->bind_param('iss',$id,$_POST['date_jour'],$st);$s->execute();}header('Location:presences.php?ok=1');break;case 'enregistrer_parametres':setcookie('langue',($_POST['langue']??'fr')==='en'?'en':'fr',time()+31536000,'/');setcookie('mode',($_POST['mode']??'clair')==='sombre'?'sombre':'clair',time()+31536000,'/');header('Location:parametres.php');break;}exit;
